import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { createUser, resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates the user, signs them in, and returns 201 {token, user}", async () => {
  const res = await call("POST", "/api/signup", { email: "NEW@example.com", name: "New", password: "correct horse" });
  assert.equal(res.status, 201);
  const { token, user } = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.deepEqual(user, { id: user.id, email: "new@example.com", name: "New" });
  const me = await call("GET", "/api/me", undefined, token);
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signup rejects a duplicate email and invalid input with 400", async () => {
  createUser("ada@example.com", "Ada", "correct horse");
  assert.equal((await call("POST", "/api/signup", { email: "ada@example.com", name: "A", password: "correct horse" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "nope", name: "A", password: "correct horse" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "x@y.com", name: "X", password: "short" })).status, 400);
  assert.equal((await call("POST", "/api/signup", { email: "x@y.com" })).status, 400);
});

test("a UserError message is returned as 400 {error}", async () => {
  createUser("ada@example.com", "Ada", "correct horse");
